//! Canonical entry surface for TheoremWeb.
//!
//! Product navigation lives in [`theoremweb_app`]. Both targets bind it to the
//! same GPUI shell: natively through the platform's own window, in the browser
//! through `gpui_web`. The split is target-based, contains no optional feature
//! and no default-off registration path, and -- since
//! HANDOFF-THEOREMWEB-SHELL-1.1 D1 -- no second renderer. There is one
//! `EnvironmentView`, drawn by one renderer, on both.

#[cfg(not(target_arch = "wasm32"))]
use std::sync::OnceLock;

pub use theoremweb_app::{
    AppEvent, AppState, AppTransition, BUILTIN_SETTINGS_PAGES, BUILTIN_SURFACES, ProductSurface,
    SettingsPage,
};

pub use theoremweb_gpui_host::{ShellPreferencesStore, WorkspaceInputs};

