pub mod desktop;

/// The reactor the native transports are driven by.
///
/// Every native transport in this product -- the chat authority, the project
/// file client, the Index panel -- is `reqwest`, and `reqwest` cannot be polled
/// outside a Tokio runtime: it resolves its connector through
/// `tokio::runtime::Handle::current()`, which panics with
///
/// ```text
/// there is no reactor running, must be called from the context of a Tokio 1.x runtime
/// ```
///
/// GPUI's executors are not Tokio. A native shell with no reactor therefore does
/// not fail a fetch, it dies inside one: the panic unwinds out of a future being
/// polled from Objective-C's run loop, where unwinding is not permitted, so the
/// process aborts (`fatal runtime error: failed to initiate panic`) and the
/// window disappears with no transcript and nothing in its log. That is the
/// signature this reactor removes.
///
/// Entered once, for the process, rather than per request. `Handle::current()`
/// is thread-local and GPUI polls every foreground task -- and every driver
/// started by [`theoremweb_gpui_host::open_window`] -- on the thread this
/// function is entered from, so the reactor has to be in scope wherever a
/// transport future is polled. The worker threads below are what actually drive
/// the reactor's I/O and timer wheels while that happens; two is the same
/// footprint Zed's `gpui_tokio::init` uses for the same two-executor reason.
///
/// The runtime is never dropped, deliberately: it is the process's reactor, and
/// a shell that is still drawing windows is still allowed to fetch.
///
/// # Panics
///
/// Panics if the reactor cannot start. A shell that can never reach an
/// authority has nothing to draw, so this is a broken installation rather than a
/// runtime condition to recover from.
#[cfg(not(target_arch = "wasm32"))]
pub fn native_reactor() -> &'static tokio::runtime::Runtime {
    static REACTOR: OnceLock<tokio::runtime::Runtime> = OnceLock::new();
    REACTOR.get_or_init(|| {
        tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_name("theoremweb-reactor")
            .enable_all()
            .build()
            .expect("the native TheoremWeb reactor could not start")
    })
}

/// Run the native TheoremWeb application with caller-owned document and
/// records authorities.
///
/// This is the normal native composition edge: the product facade starts the
/// GPUI platform, installs the shared component and token globals, and opens
/// the connected records/document host.
#[cfg(not(target_arch = "wasm32"))]
pub fn run_native(inputs: WorkspaceInputs) {
    // Before the platform, because the composition inside `run` starts its
    // drivers, and the first thing a driver does is fetch. See
    // [`native_reactor`] for what happens without this line.
    let _reactor = native_reactor().enter();
    gpui_platform::application()
        .with_assets(agpui::kit::Assets)
        .run(move |cx| {
            theoremweb_gpui_host::init(cx);
            theoremweb_gpui_host::open_window(inputs, cx);
        });
}

